import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { routerMarker } from '../process.js';
import { routePath } from '../lifecycle/manifest.js';
import { stableEntry } from './stable-layout.js';

const quote = (value: string) => "'" + value.replaceAll("'", "'\\''") + "'";

export async function renderFiles(
  commands: readonly string[],
): Promise<Map<string, string | Buffer>> {
  // Preserve setup's historical CLI/vendor anchors in both src and dist.
  // Relocation must never rebind recorded launchers or change generated bytes.
  const cli = fileURLToPath(new URL('../cli.js', import.meta.url));
  const entry = await stableEntry();
  const contents = new Map<string, string | Buffer>([
    [routePath, '# Generated by Arch.\n[env]\n_.path = ["{{config_root}}/.arch/bin"]\n'],
    ['.arch/bin/.arch-router', routerMarker],
  ]);
  for (const command of commands) {
    if ('win32' === process.platform) {
      if (!['x64', 'arm64'].includes(process.arch)) {
        throw new Error('Windows bootstrap supports x64 and arm64');
      }
      const shim = await readFile(
        new URL(`../../vendor/shim-${process.arch}.exe`, import.meta.url),
      );
      contents.set(`.arch/bin/${command}.exe`, shim);
      contents.set(
        `.arch/bin/${command}.shim`,
        entry
          ? `path = ${entry}\nargs = run ${command} --\n`
          : `path = ${process.execPath}\nargs = "${cli}" run ${command} --\n`,
      );
    } else {
      contents.set(
        `.arch/bin/${command}`,
        entry
          ? `#!/bin/sh\nexec ${quote(entry)} run ${quote(command)} -- "$@"\n`
          : `#!/bin/sh\nexec ${quote(process.execPath)} ${quote(cli)} run ${quote(command)} -- "$@"\n`,
      );
    }
  }
  return contents;
}
